(async function() {
  const $ = id => document.getElementById(id);
  const $$ = sel => document.querySelectorAll(sel);

  // 检查环境
  if (typeof getAllVariables !== 'function' || typeof _ === 'undefined') {
    console.warn("MVU 环境未就绪");
    return;
  }

  // 味道主题映射
  const FLAVOR_MAP = {
    '苏瑶': ['薄荷', '樱桃'],
    '苏双双': ['玉兰', '荔枝'],
    '叶婉秋': ['玫瑰', '红酒']
  };

  // 敏感度阶梯定义
  const SENS_LEVELS = ['青涩', '觉醒', '渴求', '失控', '享乐', '纵情', '畅爽', '绝巅', '爽泄', '登仙', '纵欲', '欢愉'];

  let currentTab = '苏瑶';
  let mvuData = {};

  // --- 1. 数据读取与写入 ---
  const DataManager = {
    load() {
      mvuData = getAllVariables();
    },
    async update(path, value) {
      if (typeof Mvu === 'undefined' || typeof getCurrentMessageId !== 'function') return false;
      try {
        const msgId = getCurrentMessageId();
        const data = Mvu.getMvuData({ type: 'message', message_id: msgId });
        if (data) {
          _.set(data, path, value);
          await Mvu.replaceMvuData(data, { type: 'message', message_id: msgId });
          mvuData = data; // 更新本地缓存
          Render.all(); // 触发重绘
          return true;
        }
      } catch (e) { console.error("MVU 写入失败", e); }
      return false;
    },
    get(path, def) {
      return _.get(mvuData, path, def);
    }
  };

  // --- 2. 渲染逻辑 ---
  const Render = {
    time() {
      const now = new Date();
      const days = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
      const str = `${now.getFullYear()}:${now.getMonth()+1}:${now.getDate()}:${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')} ${days[now.getDay()]}`;
      $('sys-time').innerText = str;
    },
    global() {
      $('sys-cash').innerText = DataManager.get('stat_data.全局.现金', 0).toFixed(1);
      $('sys-score').innerText = DataManager.get('stat_data.全局.积分', 0);
    },
    character() {
      const char = currentTab;
      const base = `stat_data.角色.${char}`;

      // 味道主题
      const flavors = FLAVOR_MAP[char] || ['未知', '未知'];
      $$('.flavor-p1').forEach(el => el.innerText = flavors[0]);

      // 头部爱意
      $('char-name-display').innerText = char;
      const loveTotal = DataManager.get(`${base}.爱意.总值`, 0);
      const loveLv = DataManager.get(`${base}.爱意.等级`, 1);
      $('love-lv').innerText = loveLv;
      $('love-title').innerText = DataManager.get(`${base}.爱意.称号`, '初恋');
      $('love-val').innerText = loveTotal;
      $('love-bar').style.width = `${(loveTotal % 100)}%`;

      // 状态区
      $('climax-count').innerText = DataManager.get(`${base}.圆融计数`, 0);

      const favor = DataManager.get(`${base}.好感度`, 0);
      $('favor-val').innerText = `${favor}/100`;
      $('favor-bar').style.width = `${Math.min(100, favor)}%`;
      // 好感度溢出特效
      if(favor >= 150) {
        $('favor-bar').style.boxShadow = '0 0 15px var(--neon-pink), 0 0 5px #fff';
      } else {
        $('favor-bar').style.boxShadow = '0 0 8px var(--neon-pink)';
      }

      const sensLv = DataManager.get(`${base}.当前显示敏感等级`, '青涩');
      $('sens-val').innerText = sensLv;
      const sensIdx = SENS_LEVELS.indexOf(sensLv);
      $('sens-bar').style.width = `${Math.min(100, (sensIdx + 1) * (100 / SENS_LEVELS.length))}%`;

      // 体液
      $('fluid-jin').innerText = DataManager.get(`${base}.体液.津液`, '湿润拉丝');
      $('fluid-han').innerText = DataManager.get(`${base}.体液.清汗`, '微微渗出');
      $('fluid-zu').innerText = DataManager.get(`${base}.体液.足汗`, '干爽');
      $('fluid-xian').innerText = DataManager.get(`${base}.体液.仙元`, '尚未动情');
      $('fluid-ling').innerText = DataManager.get(`${base}.体液.灵泉`, '紧闭');
      $('fluid-lan').innerText = DataManager.get(`${base}.体液.兰露`, '干涩');

      // 部位
      const parts = ['香舌', '奶子', '小穴', '菊蕊'];
      const partIds = ['tongue', 'boob', 'pussy', 'ass'];
      parts.forEach((p, i) => {
        const id = partIds[i];
        const exp = DataManager.get(`${base}.部位.${p}.经验`, 0);
        $(`part-${id}-lv`).innerText = DataManager.get(`${base}.部位.${p}.等级`, 0);
        $(`part-${id}-exp`).innerText = exp;
        $(`part-${id}-st`).innerText = DataManager.get(`${base}.部位.${p}.状态`, '未开发');
        $(`part-${id}-bar`).style.setProperty('--percent', exp);
      });

      // 装备
      $('eq-up').innerText = DataManager.get(`${base}.装备.上身.名称`, '无');
      $('eq-up-st').innerText = DataManager.get(`${base}.装备.上身.状态`, '完好');
      $('eq-down').innerText = DataManager.get(`${base}.装备.下身.名称`, '无');
      $('eq-down-st').innerText = DataManager.get(`${base}.装备.下身.状态`, '完好');
      $('eq-inup').innerText = DataManager.get(`${base}.装备.内衣.名称`, '无');
      $('eq-inup-st').innerText = DataManager.get(`${base}.装备.内衣.状态`, '完好');
      $('eq-indown').innerText = DataManager.get(`${base}.装备.内裤.名称`, '无');
      $('eq-indown-st').innerText = DataManager.get(`${base}.装备.内裤.状态`, '完好');
      $('eq-leg').innerText = DataManager.get(`${base}.装备.美腿`, '裸露');
      $('eq-foot').innerText = DataManager.get(`${base}.装备.玉足`, '赤足');

      // 配饰与性癖 (动态生成以绑定事件)
      this.renderArrayItems('acc-container', `${base}.配饰`, 8, '无');
      this.renderArrayItems('fetish-container', `${base}.性癖`, 3, '未觉醒');

      // 内心
      $('inner-text').innerText = DataManager.get(`${base}.内心`, '很期待接下来发生的事');
    },

    renderArrayItems(containerId, path, count, defVal) {
      const container = $(containerId);
      container.innerHTML = '';
      const arr = DataManager.get(path, Array(count).fill(defVal));
      for(let i=0; i<count; i++) {
        const val = arr[i] || defVal;
        const div = document.createElement('div');
        div.className = containerId.includes('acc') ? 'acc-item' : 'fetish-item';
        div.innerText = val;

        // 双击内联编辑
        div.addEventListener('dblclick', function() {
          if(this.querySelector('input')) return;
          const input = document.createElement('input');
          input.className = 'inline-input';
          input.value = val === defVal ? '' : val;
          this.innerHTML = '';
          this.appendChild(input);
          input.focus();

          const save = async () => {
            const newVal = input.value.trim() || defVal;
            arr[i] = newVal;
            await DataManager.update(path, arr);
          };
          input.addEventListener('blur', save);
          input.addEventListener('keydown', e => { if(e.key === 'Enter') input.blur(); });
        });

        container.appendChild(div);
      }
    },

    all() {
      this.time();
      this.global();
      this.character();
    }
  };

  // --- 3. 交互逻辑 ---
  const Interaction = {
    init() {
      // Tab 切换
      $$('.tab').forEach(tab => {
        tab.addEventListener('click', (e) => {
          $$('.tab').forEach(t => t.classList.remove('active'));
          e.target.classList.add('active');
          const target = e.target.dataset.target;
          if(target === 'shop') {
            $('view-character').style.display = 'none';
            $('view-char-header').style.display = 'none';
            $('view-shop').style.display = 'block';
          } else {
            $('view-character').style.display = 'block';
            $('view-char-header').style.display = 'flex';
            $('view-shop').style.display = 'none';
            currentTab = target;
            Render.character();
          }
        });
      });

      // 最小化
      $('btn-min').addEventListener('click', () => {
        $('neon-app').classList.toggle('minimized');
      });

      // 好感度转化爱意
      $('btn-favor').addEventListener('click', async () => {
        const base = `stat_data.角色.${currentTab}`;
        const favor = DataManager.get(`${base}.好感度`, 0);
        if (favor >= 150) {
          const newFavor = favor - 50;
          const loveAdd = Math.floor(Math.random() * 31) + 50; // 50~80
          const currentLove = DataManager.get(`${base}.爱意.总值`, 0);
          const newLove = currentLove + loveAdd;

          // 乐观更新UI
          $('favor-val').innerText = `${newFavor}/100`;

          // 写入MVU (Zod的transform会自动计算等级和称号)
          await DataManager.update(`${base}.好感度`, newFavor);
          await DataManager.update(`${base}.爱意.总值`, newLove);

          if(typeof triggerSlash === 'function') {
            triggerSlash(`/echo severity=success ${currentTab} 消耗50好感度，转化为 ${loveAdd} 点爱意！`);
          }
        } else {
          if(typeof triggerSlash === 'function') {
            triggerSlash(`/echo severity=warning 好感度不足150，无法转化。`);
          }
        }
      });

      // 敏感度循环切换
      $('btn-sens').addEventListener('click', async () => {
        const base = `stat_data.角色.${currentTab}`;
        const maxLv = DataManager.get(`${base}._最高敏感等级`, '青涩');
        const currentLv = DataManager.get(`${base}.当前显示敏感等级`, '青涩');

        const maxIdx = SENS_LEVELS.indexOf(maxLv);
        let currentIdx = SENS_LEVELS.indexOf(currentLv);

        // 循环逻辑：如果当前已经是最高解锁级别，则回到青涩；否则+1
        if (currentIdx >= maxIdx) {
          currentIdx = 0;
        } else {
          currentIdx++;
        }

        const newLv = SENS_LEVELS[currentIdx];
        await DataManager.update(`${base}.当前显示敏感等级`, newLv);
      });
    }
  };

  // --- 启动 ---
  DataManager.load();
  Interaction.init();
  Render.all();

  // 时间定时器
  setInterval(Render.time, 60000);

})();
</script>
